using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class SunriseTransitionCheck{static SunriseTransitionCheck(){EditorApplication.update+=Tick;}static void Tick(){if(EditorApplication.isCompiling||!File.Exists("SunriseTransitionCheck.request"))return;File.Delete("SunriseTransitionCheck.request");var c=UnityEngine.Object.FindObjectOfType<CityDayNightController>();bool old=c.IsNight;try{var shader=Shader.Find("Gangstar City/Mobile Night Sky");if(ShaderUtil.ShaderHasError(shader))throw new Exception("Sky shader error");int lights=UnityEngine.Object.FindObjectsOfType<Light>(true).Length;var day=JsonUtility.ToJson(c.presets.day);c.Apply(true);c.TransitionTo(false);float last=-100;foreach(float t in new[]{.70f,.60f,.50f,.40f,.30f,.20f,.10f,.001f}){c.PreviewBlend(t);float angle=Mathf.DeltaAngle(0,c.sun.transform.eulerAngles.x);if(angle<last-.01f)throw new Exception("Sunrise elevation reversed at "+t);last=angle;}c.Apply(true);c.TransitionTo(false);c.AdvanceTransition(20);if(Mathf.Abs(c.NightBlend-.5f)>.001)throw new Exception("Midpoint failed");c.AdvanceTransition(20);if(c.NightBlend!=0||Shader.GetGlobalFloat("_GangstarNight")!=0||c.streetLights.Any(l=>l&&l.enabled))throw new Exception("Day lights did not turn off");c.TransitionTo(true);c.AdvanceTransition(40);if(c.NightBlend!=1||Shader.GetGlobalFloat("_GangstarNight")!=1)throw new Exception("Night endpoint failed");var pose=CityLightingBuilder.Views(c.gameObject.scene).First();foreach(float amount in new[]{1f,.65f,.4f,.2f,0f}){c.SetManualBlend(amount);CityLightingBuilder.Capture(c,pose,"Sunrise-Check-"+Mathf.RoundToInt(amount*100));}if(day!=JsonUtility.ToJson(c.presets.day)||lights!=UnityEngine.Object.FindObjectsOfType<Light>(true).Length)throw new Exception("Preset or light count changed");c.Apply(old);EditorUtility.SetDirty(c);EditorSceneManager.MarkSceneDirty(c.gameObject.scene);EditorSceneManager.SaveScene(c.gameObject.scene);File.WriteAllText("FinalEnvironmentRoadReview/SunriseTransitionCheck.txt","SUCCESS 40-second day/night endpoints, sunrise elevation monotonic, daytime emission global=0 and street lights disabled, night emission=1. Day preset unchanged. Scene light count="+lights+" unchanged. Shared sky shader passes; no new materials/textures/reflection probes. Existing one directional light reused for sunrise/moonlight.");}catch(Exception e){c.Apply(old);File.WriteAllText("FinalEnvironmentRoadReview/SunriseTransitionCheck.txt",e.ToString());}}}
